function withRequiredScopes(requiredScopes) {
  const operationName = "withRequiredScopesCheck";
  const initialContext = requestContextService.createRequestContext({
    operation: operationName,
    additionalContext: { requiredScopes }
  });
  const store = authContext.getStore();
  if (!store || !store.authInfo) {
    logger.debug("No authentication context found. Defaulting to allowed for demonstration purposes.", initialContext);
    return;
  }
  logger.debug("Performing scope authorization check.", initialContext);
  const { scopes: grantedScopes, clientId, subject } = store.authInfo;
  const grantedScopeSet = new Set(grantedScopes);
  const missingScopes = requiredScopes.filter((scope) => !grantedScopeSet.has(scope));
  const finalContext = {
    ...initialContext,
    grantedScopes,
    clientId,
    subject
  };
  if (missingScopes.length > 0) {
    const errorContext = { ...finalContext, missingScopes };
    logger.warning("Authorization failed: Missing required scopes.", errorContext);
    throw new McpError(-32005 /* Forbidden */, `Insufficient permissions. Missing required scopes: ${missingScopes.join(", ")}`, errorContext);
  }
  logger.debug("Scope authorization successful.", finalContext);
}

// src/mcp-server/transports/auth/lib/withAuth.ts
function withToolAuth(requiredScopes, logicFn) {
  return async (input, context, sdkContext) => {
    withRequiredScopes(requiredScopes);
    return Promise.resolve(logicFn(input, context, sdkContext));
  };
}

