// src/mcp-server/tools/utils/ageParser.ts
function parseAge(ageString) {
  if (!ageString)
    return null;
  if (/^(N\/A|None|Unknown|-)$/i.test(ageString.trim())) {
    return null;
  }
  const match = ageString.match(/(\d+\.?\d*)\s*(Year|Month|Week|Day)/i);
  if (!match || !match[1] || !match[2])
    return null;
  const value = parseFloat(match[1]);
  const unit = match[2].toLowerCase();
  if (unit.startsWith("year"))
    return value;
  if (unit.startsWith("month"))
    return value / 12;
  if (unit.startsWith("week"))
    return value / 52;
  if (unit.startsWith("day"))
    return value / 365;
  return null;
}
function checkAgeEligibility(minimumAge, maximumAge, patientAge) {
  const minAge = parseAge(minimumAge);
  const maxAge = parseAge(maximumAge);
  if (minAge !== null && patientAge < minAge) {
    return { eligible: false, reason: `Below minimum age (${minAge})` };
  }
  if (maxAge !== null && patientAge > maxAge) {
    return { eligible: false, reason: `Above maximum age (${maxAge})` };
  }
  const minDisplay = minAge !== null ? minAge.toString() : "any";
  const maxDisplay = maxAge !== null ? maxAge.toString() : "any";
  return {
    eligible: true,
    reason: `Age ${patientAge} within eligible range (${minDisplay}-${maxDisplay})`
  };
}

// src/mcp-server/tools/utils/eligibilityCheckers.ts
function checkSexEligibility(studySex, patientSex) {
  const normalizedStudySex = (studySex ?? "All").toLowerCase();
  const normalizedPatientSex = patientSex.toLowerCase();
  if (normalizedStudySex === "all") {
    return { eligible: true, reason: "Study accepts all sexes" };
  }
  if (normalizedStudySex === normalizedPatientSex) {
    return {
      eligible: true,
      reason: `Study accepts ${patientSex}`
    };
  }
  return {
    eligible: false,
    reason: `Study only accepts ${studySex}`
  };
}
function checkHealthyVolunteerEligibility(studyAcceptsHealthyVolunteers, isHealthyVolunteer) {
  const acceptsHealthyVolunteers = studyAcceptsHealthyVolunteers ?? false;
  if (isHealthyVolunteer && !acceptsHealthyVolunteers) {
    return {
      eligible: false,
      reason: "Study does not accept healthy volunteers"
    };
  }
  if (!isHealthyVolunteer && acceptsHealthyVolunteers) {
    return {
      eligible: true,
      reason: "Study accepts participants with conditions"
    };
  }
  return {
    eligible: true,
    reason: "Eligibility status matches study requirements"
  };
}

// src/mcp-server/tools/utils/studyExtractors.ts
function extractRelevantLocations(study, patientLocation) {
  const locations = study.protocolSection?.contactsLocationsModule?.locations;
  if (!locations || locations.length === 0)
    return [];
  const relevantLocations = [];
  for (const loc of locations) {
    if (loc.country) {
      relevantLocations.push({
        facility: loc.facility,
        city: loc.city,
        state: loc.state,
        country: loc.country
      });
    }
  }
  relevantLocations.sort((a, b) => {
    const aCity = patientLocation.city && a.city?.toLowerCase() === patientLocation.city.toLowerCase();
    const bCity = patientLocation.city && b.city?.toLowerCase() === patientLocation.city.toLowerCase();
    if (aCity && !bCity)
      return -1;
    if (!aCity && bCity)
      return 1;
    const aState = patientLocation.state && a.state?.toLowerCase() === patientLocation.state.toLowerCase();
    const bState = patientLocation.state && b.state?.toLowerCase() === patientLocation.state.toLowerCase();
    if (aState && !bState)
      return -1;
    if (!aState && bState)
      return 1;
    return 0;
  });
  return relevantLocations;
}
function extractContactInfo(study) {
  const contacts = study.protocolSection?.contactsLocationsModule?.centralContacts;
  if (!contacts || contacts.length === 0) {
    return;
  }
  const primaryContact = contacts[0];
  return {
    name: primaryContact?.name,
    phone: primaryContact?.phone,
    email: primaryContact?.email
  };
}
function extractStudyDetails(study) {
  const statusModule = study.protocolSection?.statusModule;
  const designModule = study.protocolSection?.designModule;
  const sponsorModule = study.protocolSection?.sponsorCollaboratorsModule;
  const enrollmentInfo = designModule?.enrollmentInfo;
  return {
    phase: designModule?.phases ?? undefined,
    status: statusModule?.overallStatus ?? "Unknown",
    enrollmentCount: enrollmentInfo?.count,
    sponsor: sponsorModule?.leadSponsor?.name
  };
}

// src/mcp-server/tools/utils/studyRanking.ts
function getPhaseWeight(phases) {
  if (!phases || phases.length === 0)
    return 0;
  const phaseMap = {
    "Phase 4": 4,
    "Phase 3": 3,
    "Phase 2": 2,
    "Phase 1": 1,
    "N/A": 0,
    "Not Applicable": 0
  };
  return Math.max(...phases.map((p) => phaseMap[p] ?? 0));
}
function rankStudies(studies) {
  return [...studies].sort((a, b) => {
    if (a.matchScore !== b.matchScore) {
      return b.matchScore - a.matchScore;
    }
    const aLocationCount = a.locations.length;
    const bLocationCount = b.locations.length;
    if (aLocationCount !== bLocationCount) {
      return bLocationCount - aLocationCount;
    }
    const aPhase = getPhaseWeight(a.studyDetails.phase);
    const bPhase = getPhaseWeight(b.studyDetails.phase);
    if (aPhase !== bPhase) {
      return bPhase - aPhase;
    }
    const aEnrollment = a.studyDetails.enrollmentCount ?? 0;
    const bEnrollment = b.studyDetails.enrollmentCount ?? 0;
    return bEnrollment - aEnrollment;
  });
}
function calculateMatchScore(checks) {
  const pointsPerCheck = 25;
  const passedChecks = checks.filter((c) => c.eligible).length;
  return passedChecks * pointsPerCheck;
}

